head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil16300";
scwin.isView = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_ctxDefaults();
        scwin.init_fillGen();
        scwin.init_rowCopy();
        scwin.init_conds();
        await scwin.init_loadList();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil16300.onpageload' });
    }
};

/**
 * @method
 * @name init_ctxDefaults
 * @description 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다. 진입 기본값 충전 — 파라미터로 안 온 키에 스펙 기본값(조건 평가보다 먼저).
 * @returns {void}
 * @hidden N
 */
scwin.init_ctxDefaults = function () {
    const cds = {"isView":"N"};
    const pc0 = $c.util.getComponent("dma_pageContext");
    if (!pc0 || !pc0.get || !pc0.set) { return; }
    for (let ck in cds) { const cv0 = pc0.get(ck); if (cv0 === undefined || cv0 === null || cv0 === '') { pc0.set(ck, cds[ck]); } }
};

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — helpClssId

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_when_21", fn: function(){ return ((dlt_faqClssList.getCellData(0, "helpClssId") ?? (() => { throw new Error("unresolved:" + "faqClss.helpClssId"); })())===(dma_pageContext.get("helpClssId") ?? "")); } }, { id: "c_otherwise_24", fn: function(){ return (!(((dlt_faqClssList.getCellData(0, "helpClssId") ?? (() => { throw new Error("unresolved:" + "faqClss.helpClssId"); })())===(dma_pageContext.get("helpClssId") ?? "")))); } }, { id: "if_last", fn: function(){ return (!(dma_stat.get("last") ?? (() => { throw new Error("unresolved:" + "stat.last"); })())); } }, { id: "c_when_69", fn: function(){ return ((dlt_faqList.getCellData(0, "clssLevel") ?? (() => { throw new Error("unresolved:" + "faqList.clssLevel"); })()) === '2'); } }, { id: "c_when_73", fn: function(){ return ((dlt_faqList.getCellData(0, "clssLevel") ?? (() => { throw new Error("unresolved:" + "faqList.clssLevel"); })()) === '3'); } }, { id: "c_when_77", fn: function(){ return ((dlt_faqList.getCellData(0, "clssLevel") ?? (() => { throw new Error("unresolved:" + "faqList.clssLevel"); })()) === '4'); } }, { id: "if_isView", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.isView !== "undefined" && scwin.isView !== null ? scwin.isView : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "isView" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("isView")) === 'Y'); } }, { id: "if_faqVO", fn: function(){ return (!(String(((dlt_faqList.getCellData(0, "faqVO") ?? (() => { throw new Error("unresolved:" + "faqList.faqVO"); })())) == null ? '' : ((dlt_faqList.getCellData(0, "faqVO") ?? (() => { throw new Error("unresolved:" + "faqList.faqVO"); })()))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_19", entity: "dlt_faqClssList", countIds: [], cells: [{ childId: "__rc0", fn: function (v, i) { return String(v("helpClssNm")); } }, { childId: "__rc1", fn: function (v, i) { return String(v("helpClssNm")); } }] },
        { genId: "c_foreach_87", entity: "dlt_faqListFaqVO", countIds: [], cells: [{ childId: "__rc3", fn: function (v, i) { return String(v("quesContn")); } }, { childId: "__rc4", fn: function (v, i) { return String(v("ansContn")); } }] },
        { genId: "c_foreach_66", entity: "dlt_faqList", countIds: [], cells: [{ childId: "__rc2", fn: function (v, i) { return String(v("helpClssNm")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_keyword", fn: function () { return String((dma_pageContext.get("keyword") ?? "")); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.initValue();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil16300.onpageload' }); }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_action). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name td_25_onclick
 * @description td_25 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.td_25_onclick = async function(e){
    try {
        await scwin.searchFaq('' + dlt_faqClssList.getCellData(0, "helpClssId") + '')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil16300.td_25_onclick' }); }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「검색」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function(e){
    try {
        await scwin.search()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil16300.btn_Search_onclick' }); }
};

/**
 * @method
 * @name btn_Print_onclick
 * @description 「인쇄」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_Print_onclick = async function(e){
    try {
        await scwin.print()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil16300.btn_Print_onclick' }); }
};

/**
 * @method
 * @name table_91_onclick
 * @description table_91 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.table_91_onclick = function(e){
    try {
        scwin.viewAnswer('' + dlt_faqListFaqVO.getCellData(0, "faqId") + '')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil16300.table_91_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_SearchFaq
 * @description Search Faq 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_SearchFaq = async function () {
    const sbmOptions = {
        id: "tx_fn_SearchFaq",
        method: "post",
        action: "/support/faq.do",
        ref: "dma_SearchFaqReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_Search
 * @description Search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Search = async function () {
    const sbmOptions = {
        id: "tx_fn_Search",
        method: "post",
        action: "/support/faq.do",
        ref: "dma_SearchReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_load_list
 * @description load list 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/support/faq.do",
        ref: "dma_loadListReq",
        target: "dlt_faqClssList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name searchFaq
 * @description search Faq 처리
 * @param {String} _helpClssId _helpClssId
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchFaq = async function (_helpClssId) {
    const frm = (document.faqForm || { elements: [] });
    $c.util.getComponent('dma_SearchFaqReq').set('helpClssId', _helpClssId);
    $c.util.getComponent("ipt_keyword").setValue('');
    frm.action = 'faq.do';
    $c.util.getComponent('dma_SearchFaqReq').set('method', 'searchFAQ');
    await scwin.tx_fn_SearchFaq();
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    const frm = (document.faqForm || { elements: [] });
    $c.util.getComponent('dma_SearchFaqReq').set('helpClssId', $c.util.getComponent('slc_helpClssIdSel').getValue());
    frm.action = 'faq.do';
    $c.util.getComponent('dma_SearchFaqReq').set('method', 'searchFAQ');
    await scwin.tx_fn_Search();
};

/**
 * @method
 * @name print
 * @description print 처리
 * @returns {void}
 * @hidden N
 */
scwin.print = async function () {
    await $c.win.print();
};

/**
 * @method
 * @name viewAnswer
 * @description view Answer 처리
 * @param {String} _faqId _faqId
 * @returns {void}
 * @hidden N
 */
scwin.viewAnswer = function (_faqId) {
    const divObj = $c.util.getComponent('answer_' + _faqId);
    const dispalyVal = divObj.style.display;
    if (dispalyVal === 'none') {
        divObj.style.display = 'inline';
    } else {
        if (dispalyVal === 'inline') {
            divObj.style.display = 'none';
        }
    }
};

/**
 * @method
 * @name initValue
 * @description init Value 처리
 * @returns {void}
 * @hidden N
 */
scwin.initValue = function () {
    const frm = (document.faqForm || { elements: [] });
    $c.util.getComponent("slc_helpClssIdSel").setValue("" + dma_pageContext.get("helpClssIdSel") + "");
};
